import { encodeAbiParameters, keccak256 } from "viem";
import { MarketParams, marketParamsAbi, } from "../../market/index.js";
import { CapacityLimitReason } from "../../utils.js";
import { VaultV2Adapter } from "./VaultV2Adapter.js";
export class VaultV2MorphoMarketV1AdapterV2 extends VaultV2Adapter {
    static adapterId(address) {
        return keccak256(encodeAbiParameters([{ type: "string" }, { type: "address" }], ["this", address]));
    }
    static collateralId(address) {
        return keccak256(encodeAbiParameters([{ type: "string" }, { type: "address" }], ["collateralToken", address]));
    }
    static marketParamsId(address, params) {
        return keccak256(encodeAbiParameters([{ type: "string" }, { type: "address" }, marketParamsAbi], ["this/marketParams", address, params]));
    }
    marketIds;
    adaptiveCurveIrm;
    supplyShares;
    constructor({ marketIds, adaptiveCurveIrm, supplyShares, ...vaultV2Adapter }) {
        super({
            ...vaultV2Adapter,
            type: "VaultV2MorphoMarketV1AdapterV2",
            adapterId: VaultV2MorphoMarketV1AdapterV2.adapterId(vaultV2Adapter.address),
        });
        this.marketIds = marketIds;
        this.adaptiveCurveIrm = adaptiveCurveIrm;
        this.supplyShares = supplyShares;
    }
    ids(params) {
        return [
            this.adapterId,
            VaultV2MorphoMarketV1AdapterV2.collateralId(params.collateralToken),
            VaultV2MorphoMarketV1AdapterV2.marketParamsId(this.address, params),
        ];
    }
}
export class AccrualVaultV2MorphoMarketV1AdapterV2 extends VaultV2MorphoMarketV1AdapterV2 {
    markets;
    constructor(adapter, markets) {
        super(adapter);
        this.markets = markets;
    }
    realAssets(timestamp) {
        return this.markets.reduce((total, market) => total +
            market
                .accrueInterest(timestamp)
                .toSupplyAssets(this.supplyShares[market.id] ?? 0n), 0n);
    }
    maxDeposit(_data, assets) {
        return {
            value: BigInt(assets),
            limiter: CapacityLimitReason.balance,
        };
    }
    maxWithdraw(data) {
        const marketId = MarketParams.fromHex(data).id;
        // biome-ignore lint/nursery/noShadow: TODO rename to avoid shadowing
        const market = this.markets.find((market) => market.id === marketId);
        return (market?.getWithdrawCapacityLimit({
            supplyShares: this.supplyShares[marketId] ?? 0n,
        }) ?? {
            value: 0n,
            limiter: CapacityLimitReason.position,
        });
    }
}
